<?php
require_once __DIR__.'/includes/bootstrap.php';$code=trim($_GET['code']??'');$record=null;
if($code!==''){$stmt=db()->prepare("SELECT cert.certificate_number,cert.issue_date,cert.status,u.full_name,e.title,e.event_date,c.club_name FROM certificate cert JOIN attendance a ON a.attendance_id=cert.attendance_id JOIN event_registration er ON er.registration_id=a.registration_id JOIN users u ON u.user_id=er.student_user_id JOIN events e ON e.event_id=er.event_id JOIN clubs c ON c.club_id=e.club_id WHERE cert.verification_code=?");$stmt->execute([$code]);$record=$stmt->fetch();}
$pageTitle='Verify certificate';require __DIR__.'/includes/header.php';?>
<section class="page-shell verify-page"><div class="page-head"><div><span class="eyebrow">PUBLIC RECORD CHECK</span><h2>Verify a CampusHub<br><span class="accent-script">achievement.</span></h2></div></div><form class="card verify-form" method="get"><div class="field"><label>Verification code</label><input name="code" required value="<?=e($code)?>" placeholder="Enter the code printed on the certificate"></div><button class="button button-primary">Verify certificate</button></form><?php if($code!==''):?><article class="verification-result <?=$record&&$record['status']==='Active'?'valid':'invalid'?>"><?php if($record):?><span class="eyebrow"><?=$record['status']==='Active'?'VALID CERTIFICATE':'REVOKED CERTIFICATE'?></span><h3><?=e($record['full_name'])?></h3><p>Participated in <strong><?=e($record['title'])?></strong>, hosted by <?=e($record['club_name'])?> on <?=e(date('F j, Y',strtotime($record['event_date'])))?>.</p><small><?=e($record['certificate_number'])?> · issued <?=e(date('F j, Y',strtotime($record['issue_date'])))?></small><?php else:?><span class="eyebrow">NOT FOUND</span><h3>This code does not match a CampusHub certificate.</h3><?php endif;?></article><?php endif;?></section><?php require __DIR__.'/includes/footer.php';?>
